-- ============================================================================ -- supabase/migrations/phase9_superadmin_global.sql -- PHASE 9 — GLOBAL SUPERADMIN PLATFORM MANAGEMENT -- -- SAFETY: purely additive. No DROP TABLE/COLUMN/FUNCTION. -- No existing table, RLS policy, or Authentication file/function touched. -- Every RPC re-verifies superadmin server-side via auth.uid(). -- Uses only REAL schema columns confirmed in the project: --   profiles: id, full_name, phone, avatar_url, is_disabled, user_number --   schools: id, name --   user_roles: profile_id, school_id, role --   students: id, school_id, ... (deleted_at confirmed) --   teachers: id, profile_id, school_id, employee_number, deleted_at (confirmed) --   drivers: id, profile_id, school_id, license_number, deleted_at (confirmed) --   parents: id, profile_id, school_id, deleted_at (confirmed) --   guards: id, profile_id, school_id (deleted_at NOT confirmed) --   guard_permissions: id, profile_id, permission_id, school_id, granted_by, created_at --   audit_logs: id, school_id, action, entity, entity_id, old_value, new_value, created_at, actor_id --   permissions: id, permission_key, module, name, description, created_at -- -- No references to: profiles.role, profiles.school_id, profiles.deleted_at, -- profiles.is_active, schools.email, schools.deleted_at. -- ============================================================================  -- ============================================================================ -- SECTION A: RLS POLICIES — SuperAdmin SELECT on all platform tables. -- These are ADDITIVE (new policies) — existing policies are untouched. -- SuperAdmin gets READ-ONLY global visibility; mutations go through RPCs. -- -- SECURITY NOTE: All policies use fn_is_superadmin() (SECURITY DEFINER) -- instead of inline subqueries. This prevents infinite recursion on user_roles -- and ensures consistent, performant checks across all tables. -- ============================================================================  -- A.1 profiles: SuperAdmin can read ALL profiles (global user directory). create policy p_profiles_superadmin_read on profiles for select using (     fn_is_superadmin() );  -- A.2 user_roles: SuperAdmin can read ALL role assignments. -- CRITICAL: uses fn_is_superadmin() to avoid infinite recursion (selecting -- user_roles inside an RLS policy on user_roles would recurse forever). create policy p_user_roles_superadmin_read on user_roles for select using (     fn_is_superadmin() );  -- A.3 schools: SuperAdmin can read ALL schools. create policy p_schools_superadmin_read on schools for select using (     fn_is_superadmin() );  -- A.4 students: SuperAdmin can read ALL students. create policy p_students_superadmin_read on students for select using (     fn_is_superadmin() );  -- A.5 teachers: SuperAdmin can read ALL teachers. create policy p_teachers_superadmin_read on teachers for select using (     fn_is_superadmin() );  -- A.6 drivers: SuperAdmin can read ALL drivers. create policy p_drivers_superadmin_read on drivers for select using (     fn_is_superadmin() );  -- A.7 parents: SuperAdmin can read ALL parents. create policy p_parents_superadmin_read on parents for select using (     fn_is_superadmin() );  -- A.8 guards: SuperAdmin can read ALL guards. create policy p_guards_superadmin_read on guards for select using (     fn_is_superadmin() );    -- A.10 audit_logs: SuperAdmin can read ALL audit entries. create policy p_audit_logs_superadmin_read on audit_logs for select using (     fn_is_superadmin() );  -- ============================================================================ -- SECTION B: HELPER FUNCTIONS -- ============================================================================  -- B.1 fn_count_superadmins — returns how many superadmin rows exist. --    Used by role-removal safety checks. create or replace function fn_count_superadmins() returns bigint language sql stable security definer set search_path = public as $$   select count(*) from user_roles where role::text = 'superadmin'; $$; revoke all on function fn_count_superadmins() from public; grant execute on function fn_count_superadmins() to authenticated;  -- B.2 fn_is_last_superadmin — returns true if the given profile is the ONLY --    superadmin left in the system. create or replace function fn_is_last_superadmin(p_profile_id uuid) returns boolean language sql stable security definer set search_path = public as $$   select exists (     select 1 from user_roles     where profile_id = p_profile_id and role::text = 'superadmin'   )   and (select count(*) from user_roles where role::text = 'superadmin') = 1; $$; revoke all on function fn_is_last_superadmin(uuid) from public; grant execute on function fn_is_last_superadmin(uuid) to authenticated;  -- ============================================================================ -- SECTION C: PLATFORM STATISTICS (Enhanced) -- ============================================================================  -- C.1 fn_get_platform_stats_enhanced — comprehensive platform stats. --    SuperAdmin only. Returns counts by role type. --    NOTE: guards table does NOT have deleted_at in the confirmed schema, --    so we count ALL guard rows. Teachers/drivers/parents/students DO have --    deleted_at per the existing codebase (accounts.js, students.js). create or replace function fn_get_platform_stats_enhanced() returns table(   total_schools bigint,   total_profiles bigint,   total_students bigint,   total_guard_checks bigint,   total_admins bigint,   total_directors bigint,   total_teachers bigint,   total_guards bigint,   total_drivers bigint,   total_parents bigint,   total_superadmins bigint,   disabled_profiles bigint ) language plpgsql security definer set search_path = public as $$ begin   if not fn_is_superadmin() then     raise exception 'PERMISSION_DENIED';   end if;    return query   select     (select count(*) from schools),     (select count(*) from profiles),     (select count(*) from students where deleted_at is null),     (select count(*) from guard_checks),     (select count(distinct profile_id) from user_roles where role::text = 'admin'),     (select count(distinct profile_id) from user_roles where role::text = 'director'),     (select count(*) from teachers where deleted_at is null),     (select count(*) from guards),     (select count(*) from drivers where deleted_at is null),     (select count(*) from parents where deleted_at is null),     (select count(distinct profile_id) from user_roles where role::text = 'superadmin'),     (select count(*) from profiles where is_disabled = true); end; $$; revoke all on function fn_get_platform_stats_enhanced() from public; grant execute on function fn_get_platform_stats_enhanced() to authenticated;  -- ============================================================================ -- SECTION D: USER MANAGEMENT -- ============================================================================  -- D.1 fn_list_all_users — paginated global user directory. --    Returns profile + aggregated role info. SuperAdmin only. create or replace function fn_list_all_users(p_query text default null, p_limit int default 50, p_offset int default 0) returns table(   profile_id uuid,   full_name text,   user_number text,   phone text,   is_disabled boolean,   roles jsonb,   school_names jsonb ) language plpgsql security definer set search_path = public as $$ begin   if not fn_is_superadmin() then     raise exception 'PERMISSION_DENIED';   end if;    return query   select     p.id as profile_id,     p.full_name,     p.user_number,     p.phone,     p.is_disabled,     coalesce(       (select jsonb_agg(distinct ur.role::text) from user_roles ur where ur.profile_id = p.id),       '[]'::jsonb     ) as roles,     coalesce(       (select jsonb_agg(distinct s.name) from user_roles ur join schools s on s.id = ur.school_id where ur.profile_id = p.id),       '[]'::jsonb     ) as school_names   from profiles p   where (p_query is null or p_query = '' or p.full_name ilike '%' || p_query || '%' or p.user_number ilike '%' || p_query || '%')   order by p.full_name   limit p_limit offset p_offset; end; $$; revoke all on function fn_list_all_users(text, int, int) from public; grant execute on function fn_list_all_users(text, int, int) to authenticated;  -- D.2 fn_get_user_detail — full detail for one user across all schools. create or replace function fn_get_user_detail(p_profile_id uuid) returns table(   profile_id uuid,   full_name text,   user_number text,   phone text,   is_disabled boolean,   roles jsonb ) language plpgsql security definer set search_path = public as $$ begin   if not fn_is_superadmin() then     raise exception 'PERMISSION_DENIED';   end if;    return query   select     p.id as profile_id,     p.full_name,     p.user_number,     p.phone,     p.is_disabled,     coalesce(       (select jsonb_agg(jsonb_build_object('school_id', ur.school_id, 'school_name', s.name, 'role', ur.role::text))        from user_roles ur join schools s on s.id = ur.school_id where ur.profile_id = p.id),       '[]'::jsonb     ) as roles   from profiles p   where p.id = p_profile_id; end; $$; revoke all on function fn_get_user_detail(uuid) from public; grant execute on function fn_get_user_detail(uuid) to authenticated;  -- D.3 fn_superadmin_set_profile_status — enable/disable ANY account. --    SuperAdmin only. Prevents disabling the last superadmin. create or replace function fn_superadmin_set_profile_status(p_profile_id uuid, p_is_disabled boolean) returns void language plpgsql security definer set search_path = public as $$ declare   v_school_id uuid; begin   if not fn_is_superadmin() then     raise exception 'PERMISSION_DENIED';   end if;    -- Safety: never disable the last superadmin.   if p_is_disabled and fn_is_last_superadmin(p_profile_id) then     raise exception 'CANNOT_DISABLE_LAST_SUPERADMIN';   end if;    update profiles set is_disabled = p_is_disabled where id = p_profile_id;    -- Audit: pick any school the caller is associated with for the log.   select school_id into v_school_id from user_roles where profile_id = auth.uid() limit 1;    perform fn_write_audit(     coalesce(v_school_id, '00000000-0000-0000-0000-000000000000'::uuid),     case when p_is_disabled then 'SUPERADMIN_DISABLE_ACCOUNT' else 'SUPERADMIN_ENABLE_ACCOUNT' end,     'profiles', p_profile_id, null,     jsonb_build_object('is_disabled', p_is_disabled, 'changed_by', auth.uid())   ); end; $$; revoke all on function fn_superadmin_set_profile_status(uuid, boolean) from public; grant execute on function fn_superadmin_set_profile_status(uuid, boolean) to authenticated;  -- ============================================================================ -- SECTION E: ROLE MANAGEMENT -- ============================================================================  -- E.1 fn_superadmin_list_user_roles — all role rows for a user. create or replace function fn_superadmin_list_user_roles(p_profile_id uuid) returns table(   school_id uuid,   school_name text,   role text ) language plpgsql security definer set search_path = public as $$ begin   if not fn_is_superadmin() then     raise exception 'PERMISSION_DENIED';   end if;    return query   select ur.school_id, s.name as school_name, ur.role::text as role   from user_roles ur   join schools s on s.id = ur.school_id   where ur.profile_id = p_profile_id   order by s.name, ur.role::text; end; $$; revoke all on function fn_superadmin_list_user_roles(uuid) from public; grant execute on function fn_superadmin_list_user_roles(uuid) to authenticated;  -- E.2 fn_superadmin_assign_role — add a role to a user. --    Prevents duplicate roles per (profile, school, role). --    Only superadmin can assign superadmin role (defense in depth). create or replace function fn_superadmin_assign_role(p_profile_id uuid, p_school_id uuid, p_role text) returns void language plpgsql security definer set search_path = public as $$ declare   v_caller_is_superadmin boolean; begin   v_caller_is_superadmin := fn_is_superadmin();   if not v_caller_is_superadmin then     raise exception 'PERMISSION_DENIED';   end if;    -- Only superadmin can assign superadmin role.   if p_role = 'superadmin' and not v_caller_is_superadmin then     raise exception 'PERMISSION_DENIED: only superadmin can assign superadmin';   end if;    -- Prevent duplicate.   if exists (select 1 from user_roles where profile_id = p_profile_id and school_id = p_school_id and role::text = p_role) then     raise exception 'ROLE_ALREADY_EXISTS';   end if;    insert into user_roles (profile_id, school_id, role) values (p_profile_id, p_school_id, p_role::app_role);    perform fn_write_audit(     p_school_id, 'SUPERADMIN_ASSIGN_ROLE', 'user_roles', p_profile_id, null,     jsonb_build_object('role', p_role, 'assigned_by', auth.uid())   ); end; $$; revoke all on function fn_superadmin_assign_role(uuid, uuid, text) from public; grant execute on function fn_superadmin_assign_role(uuid, uuid, text) to authenticated;  -- E.3 fn_superadmin_remove_role — remove a role from a user. --    Prevents removing the last superadmin. --    Prevents removing a role that doesn't exist. create or replace function fn_superadmin_remove_role(p_profile_id uuid, p_school_id uuid, p_role text) returns void language plpgsql security definer set search_path = public as $$ declare   v_caller_is_superadmin boolean; begin   v_caller_is_superadmin := fn_is_superadmin();   if not v_caller_is_superadmin then     raise exception 'PERMISSION_DENIED';   end if;    -- Verify the role exists before removing.   if not exists (select 1 from user_roles where profile_id = p_profile_id and school_id = p_school_id and role::text = p_role) then     raise exception 'ROLE_NOT_FOUND';   end if;    -- Safety: never remove the last superadmin.   if p_role = 'superadmin' and fn_is_last_superadmin(p_profile_id) then     raise exception 'CANNOT_REMOVE_LAST_SUPERADMIN';   end if;    delete from user_roles where profile_id = p_profile_id and school_id = p_school_id and role::text = p_role;    perform fn_write_audit(     p_school_id, 'SUPERADMIN_REMOVE_ROLE', 'user_roles', p_profile_id, null,     jsonb_build_object('role', p_role, 'removed_by', auth.uid())   ); end; $$; revoke all on function fn_superadmin_remove_role(uuid, uuid, text) from public; grant execute on function fn_superadmin_remove_role(uuid, uuid, text) to authenticated;  -- ============================================================================ -- SECTION F: AUDIT LOGS -- ============================================================================  -- F.1 fn_superadmin_get_audit_logs — global audit log viewer. --    SuperAdmin only. Ordered newest first. create or replace function fn_superadmin_get_audit_logs(p_limit int default 50, p_offset int default 0) returns table(   id uuid,   school_id uuid,   school_name text,   action text,   entity text,   entity_id uuid,   old_value jsonb,   new_value jsonb,   created_at timestamptz,   actor_name text ) language plpgsql security definer set search_path = public as $$ begin   if not fn_is_superadmin() then     raise exception 'PERMISSION_DENIED';   end if;    return query   select     al.id, al.school_id, s.name as school_name, al.action, al.entity,     al.entity_id, al.old_value, al.new_value, al.created_at,     p.full_name as actor_name   from audit_logs al   left join schools s on s.id = al.school_id   left join profiles p on p.id = al.actor_id   order by al.created_at desc   limit p_limit offset p_offset; end; $$; revoke all on function fn_superadmin_get_audit_logs(int, int) from public; grant execute on function fn_superadmin_get_audit_logs(int, int) to authenticated;  -- F.2 fn_superadmin_get_audit_count — total audit entries for pagination. --    FIXED: uses plpgsql with explicit permission check instead of --    invalid SQL syntax. create or replace function fn_superadmin_get_audit_count() returns bigint language plpgsql security definer set search_path = public as $$ begin   if not fn_is_superadmin() then     raise exception 'PERMISSION_DENIED';   end if;   return (select count(*) from audit_logs); end; $$; revoke all on function fn_superadmin_get_audit_count() from public; grant execute on function fn_superadmin_get_audit_count() to authenticated;  -- ============================================================================ -- SECTION G: SCHOOL MANAGEMENT ENHANCEMENTS -- ============================================================================  -- G.1 fn_get_school_detail — full school stats for SuperAdmin. create or replace function fn_get_school_detail(p_school_id uuid) returns table(   school_id uuid,   school_name text,   total_students bigint,   total_teachers bigint,   total_guards bigint,   total_drivers bigint,   total_parents bigint,   total_admins bigint,   total_directors bigint ) language plpgsql security definer set search_path = public as $$ begin   if not fn_is_superadmin() then     raise exception 'PERMISSION_DENIED';   end if;    return query   select     s.id as school_id,     s.name as school_name,     (select count(*) from students st where st.school_id = p_school_id and st.deleted_at is null),     (select count(*) from teachers t where t.school_id = p_school_id and t.deleted_at is null),     (select count(*) from guards g where g.school_id = p_school_id),     (select count(*) from drivers d where d.school_id = p_school_id and d.deleted_at is null),     (select count(*) from parents pa where pa.school_id = p_school_id and pa.deleted_at is null),     (select count(distinct profile_id) from user_roles where school_id = p_school_id and role::text = 'admin'),     (select count(distinct profile_id) from user_roles where school_id = p_school_id and role::text = 'director'); end; $$; revoke all on function fn_get_school_detail(uuid) from public; grant execute on function fn_get_school_detail(uuid) to authenticated;  -- ============================================================================ -- END OF PHASE 9 SUPERADMIN GLOBAL MIGRATION -- ============================================================================